const LIGHT_LM_MIN = 100, LIGHT_LM_MAX = 10000, LIGHT_K_MIN = 2200, LIGHT_K_MAX = 6500, LIGHT_K_DEF = 2700, LIGHT_BEAM_MIN = 10, LIGHT_BEAM_MAX = 120;
