/* ---------- Görünüm ---------- */
const cv = $('#cv');
function svgSize() { const r = cv.getBoundingClientRect(); return { w: r.width, h: r.height, l: r.left, t: r.top }; }
function w2s(p) { return { x: p.x * view.z + view.x, y: p.y * view.z + view.y }; }
