  if (live) s += `<path data-id="${w.id}" d="${pd}" fill="none" stroke="transparent" stroke-width="${Math.max(accFanDepth(w) + 6, 14 / view.z)}" pointer-events="stroke" style="cursor:pointer"/>`;
