  const lin = t => ({ a: lp(A0, A1, t), b: lp(B0, B1, t) });
  const ux = B0.x - A0.x, uy = B0.y - A0.y, vx = B1.x - A1.x, vy = B1.y - A1.y, uu = ux * ux + uy * uy;
  if (uu < 1 || vx * vx + vy * vy < 1) return lin;
