      for (const [p, q] of belRoofFolds(w)) s += `<line x1="${p.x}" y1="${p.y}" x2="${q.x}" y2="${q.y}" stroke="${C.sub}" stroke-opacity="0.45" stroke-width="${sw * 0.45}" stroke-dasharray="4 4" pointer-events="none"/>`;
