  if (a === 'grpEdit') { const c = varContainer(); if (ui.grpEdit && (!c || c.type !== 'group' || c.rec.id === ui.grpEdit.id)) stopGrpEdit(); else if (c && c.type === 'group') startGrpEdit(c.rec); refresh(); return; }
