      client_id: cid, scope: GD_SCOPE, callback: gdOnToken,
      error_callback: e => { gd.status = gd.token ? 'on' : (gdCfg().on ? 'auth' : 'off'); gd.err = e && e.type === 'popup_closed' ? '' : ((e && (e.message || e.type)) || ''); gdUI(); },
