    const r = await (await gdFetch(`${GD_API}/files?q=${encodeURIComponent(q + ' and trashed=false')}&fields=${encodeURIComponent('nextPageToken,' + fields)}&pageSize=200&spaces=drive${tok ? '&pageToken=' + encodeURIComponent(tok) : ''}`)).json();
