async function shareShow(kind) {
  const out = document.getElementById('shOut'); if (!out) return;
  out.innerHTML = `<p class="muted">${L('Hazırlanıyor…', 'Preparing…')}</p>`;
  let url = '', note = '';
  try {
    if (kind === 'drive') {
      await gdSync(false);
      const st = P && gdState()[P.id];
      if (!st) throw new Error(isPristine(P) ? L('boş proje Drive’a kaydedilmez', 'an empty project is not saved to Drive') : L('proje Drive’a kaydedilemedi', 'the project could not be saved to Drive'));
      url = driveLink(st.f);
      note = L('Aynı Google hesabıyla giriş yapılan cihazda açılır ve eşitlenmeye devam eder.', 'Opens on a device signed in to the same Google account and keeps syncing.');
    } else {
      url = await shareLink(P);
      note = (P.textures || []).length ? L('Özel doku görselleri linke girmez (yüzeyler düz renk görünür); onlar için dosya gönderin ya da Google Drive kullanın.', 'Custom texture images are not in the link (surfaces show a plain colour); send a file or use Google Drive for them.') : '';
    }
  } catch (e) { out.innerHTML = `<p style="color:var(--danger)">⚠ ${esc(e.message)}</p>`; return; }
  const qr = url.length <= SHARE_QR_MAX ? qrSvg(url, url.length > 600 ? 'L' : 'M', 4) : '';
  out.innerHTML = `<div class="sh-out">
    ${qr ? `<div class="sh-qr">${qr}</div>` : `<p class="muted">${L('Bu plan bir QR koduna sığmayacak kadar büyük — linki kopyalayıp kendinize gönderin ya da Google Drive kullanın.', 'This plan is too large for a QR code — copy the link and send it to yourself, or use Google Drive.')}</p>`}
    <div class="row"><input id="shUrl" readonly value="${esc(url)}" style="flex:1;min-width:200px"><button class="btn sm primary" data-sh="copy">📋 ${L('Kopyala', 'Copy')}</button>${navigator.share ? `<button class="btn sm" data-sh="share">📤 ${L('Paylaş…', 'Share…')}</button>` : ''}</div>
    ${note ? `<p class="muted" style="font-size:12px">${note}</p>` : ''}
    <p class="muted" style="font-size:12px">${L('Link yalnızca bu projenin şu anki hâlini taşır; sonraki değişiklikler için yeni link gerekir.', 'The link carries this project as it is now; later changes need a new link.')}${kind === 'drive' ? '' : ' ' + L('Linki alan herkes planı görebilir.', 'Anyone who gets the link can see the plan.')}</p></div>`;
}
async function shareFile() {
  const name = fname('json'), blob = new Blob([JSON.stringify(bundleTextures(P))], { type: 'application/json' });
  try {
    const file = new File([blob], name, { type: 'application/json' });
    if (navigator.canShare && navigator.canShare({ files: [file] })) { await navigator.share({ files: [file], title: P.name }); return; }
  } catch (e) { if (e && e.name === 'AbortError') return; }
  download(name, blob);
  toast(L('JSON indirildi — diğer cihazda 📂 Aç ile açın', 'JSON downloaded — open it on the other device with 📂 Open'));
}
$('#modal').addEventListener('click', e => {
  if (ui.modal !== 'sync') return;
  const g = e.target.closest('[data-gd]'), o = e.target.closest('[data-gdopen]'), s = e.target.closest('[data-sh]');
  if (o) { gdOpenFile(o.dataset.gdopen); return; }
  if (e.target.closest('#gdCidSave')) {
    const v = ($('#gdCid').value || '').trim(), c = gdCfg();
    if (v && !/^[\w.-]+\.apps\.googleusercontent\.com$/.test(v)) { toast(L('Geçersiz istemci kimliği', 'Invalid client ID')); return; }
    if (v) c.cid = v; else delete c.cid; gdSetCfg(c); gd.client = null; syncModal(); return;
  }
  if (g) {
    const a = g.dataset.gd;
    if (a === 'connect') gdConnect();
    else if (a === 'sync') gdSync(true);
    else if (a === 'list') { gd.list = null; gdUI(); gdLoadList(); }
    else if (a === 'off') gdDisconnect();
    else gdResolve(a);
    return;
  }
  if (s) {
    const a = s.dataset.sh;
    if (a === 'link' || a === 'drive') shareShow(a);
    else if (a === 'file') shareFile();
    else if (a === 'collab') { closeModal(); collabModal(); }
    else if (a === 'copy') copyText($('#shUrl').value).then(ok => toast(ok ? L('Link kopyalandı', 'Link copied') : L('Kopyalanamadı — linki seçip kopyalayın', 'Could not copy — select the link and copy it')));
    else if (a === 'share') navigator.share({ title: P.name, url: $('#shUrl').value }).catch(() => { });
  }
});
// açılışta: oturum belirteci (aynı sekmede yenileme), pencereler arası kanal, #fp / #fpd linki
async function syncBoot() {
  bcInit();
  try { const t = JSON.parse(sessionStorage.getItem('fp_gd_tok') || 'null'); if (t && t.t && t.exp > Date.now() + 60000) { gd.token = t.t; gd.exp = t.exp; } } catch (e) { }
  const c = gdCfg();
  gd.status = gd.token ? 'on' : (c.on && gdUsable() ? 'auth' : 'off');
  if (c.on && gdUsable()) gdLoadGis().catch(() => { });
  gdUI();
  await openShareHash();
  if (gd.token) gdSyncSoon(800);
  setInterval(() => { if (gd.token && !document.hidden) gdSync(false); }, 60000);         // başka cihazdaki değişiklikleri al
  document.addEventListener('visibilitychange', () => { if (!document.hidden && gd.token) gdSyncSoon(400); });
}
// başkasından gelebilen link planları (#fp=): hiçbir metin bir HTML / SVG özniteliğinden taşamasın (" < > ` atılır;
// uygulamada tek tırnaklı öznitelik yok), arka plan görseli yalnızca data:image/… olabilir. Drive dosyaları kullanıcının
// kendi dosyalarıdır (drive.file: yalnız bu uygulamanın oluşturdukları), 📂 Aç gibi olduğu gibi alınır.
function sanitizePlan(o, depth = 0) {
  if (depth > 40) return null;
  if (typeof o === 'string') return o.replace(/["<>`]/g, '');
  if (typeof o === 'number') return isFinite(o) ? o : 0;
  if (Array.isArray(o)) return o.map(v => sanitizePlan(v, depth + 1));
  if (o && typeof o === 'object') {
    const r = {};
    for (const k of Object.keys(o)) if (k !== '__proto__' && k !== 'constructor' && k !== 'prototype') r[k.replace(/["<>`]/g, '')] = sanitizePlan(o[k], depth + 1);
    if (depth === 0) {
      if (r.bg && !(typeof r.bg.src === 'string' && /^data:image\/[\w.+-]+;base64,[\w+/=]+$/.test(r.bg.src))) r.bg = null;
      if (r.texData && typeof r.texData === 'object') for (const id of Object.keys(r.texData)) if (!/^data:image\/[\w.+-]+(;base64)?,/.test(r.texData[id])) delete r.texData[id];
    }
    return r;
  }
  return typeof o === 'boolean' || o === null ? o : null;
}

/* ---------- Canlı kullanıcı sayacı (isteğe bağlı Cloudflare Worker) ---------- */
// presence/worker.mjs dağıtıldıktan sonra alınan adres (ör. 'wss://floorplanner-presence.<alt-alan>.workers.dev/ws' veya 'https://...')
// ?presence=off sekmeyi kapatır; ?presence=ws://... yerel test için uç noktayı geçersiz kılar
const PRESENCE_URL = 'wss://floorplanner-presence.alieferdinc.workers.dev/ws';
const pres = { ws: null, count: null, delay: 2000, retry: null, ping: null, closed: false };
function presenceEndpoint(base = PRESENCE_URL, loc = location) {
  let q = '';
  try { q = new URLSearchParams(loc.search || '').get('presence') || ''; } catch (e) { }
  q = q.trim();
  if (/^(off|0|false)$/i.test(q)) return '';
  const ql = q.toLowerCase();
  let raw = '';
  if (ql.startsWith('ws://') || ql.startsWith('wss://') || ql.startsWith('http://') || ql.startsWith('https://')) {
    raw = q;
  } else {
    const proto = String(loc.protocol || '').toLowerCase();
    const host = String(loc.hostname || '').toLowerCase();
    if ((proto !== 'http:' && proto !== 'https:') || !host || host === 'localhost' || host === '127.0.0.1' || host === '::1' || host === '[::1]') return '';
    raw = String(base || '').trim();
  }
  if (!raw) return '';
  const rl = raw.toLowerCase();
  if (rl.startsWith('https://')) raw = 'wss://' + raw.slice(8);
  else if (rl.startsWith('http://')) raw = 'ws://' + raw.slice(7);
  try {
    const u = new URL(raw);
    if (u.protocol !== 'ws:' && u.protocol !== 'wss:') return '';
    if (!u.pathname || u.pathname === '/') u.pathname = '/ws';
    return u.toString();
  } catch (e) { return ''; }
}
function presenceParseCount(raw) {
  if (typeof raw !== 'string' || raw === 'pong') return null;
  try {
    const d = JSON.parse(raw);
    return d && typeof d.online === 'number' && Number.isFinite(d.online) && d.online >= 0 ? Math.floor(d.online) : null;
  } catch (e) { return null; }
}
function presenceLabel(n) {
  return L(`${n} kişi şu an çevrimiçi`, n === 1 ? '1 person online now' : `${n} people online now`);
}
function presenceRender() {
  const wrap = $('#onlineWrap'), cnt = $('#onlineCnt');
  if (!wrap || !cnt) return;
  if (typeof pres.count !== 'number' || !Number.isFinite(pres.count) || pres.count < 1) {
    wrap.hidden = true;
    cnt.textContent = '';
    wrap.title = '';
    wrap.removeAttribute('aria-label');
    return;
  }
  const label = presenceLabel(pres.count);
  cnt.textContent = String(pres.count);
  wrap.title = label;
  wrap.setAttribute('aria-label', label);
  wrap.hidden = false;
}
function presenceDrop(keepCount) {
  clearTimeout(pres.retry); pres.retry = null;
  clearInterval(pres.ping); pres.ping = null;
  const ws = pres.ws; pres.ws = null;
  if (ws) { try { ws.close(1000); } catch (e) { } }
  if (!keepCount) { pres.count = null; presenceRender(); }
}
function presenceSchedule(url) {
  if (pres.closed) return;
  clearTimeout(pres.retry);
  const wait = Math.round(pres.delay * (1 + Math.random() * 0.25));
  pres.delay = Math.min(60000, pres.delay * 2);
  pres.retry = setTimeout(() => presenceConnect(url), wait);
}
function presenceConnect(url) {
  if (pres.closed || pres.ws || (typeof navigator !== 'undefined' && navigator.onLine === false)) return;
  clearTimeout(pres.retry); pres.retry = null;
  let ws;
  try { ws = new WebSocket(url); } catch (e) { presenceSchedule(url); return; }
  pres.ws = ws;
  ws.onopen = () => {
    if (pres.ws !== ws) return;
    pres.delay = 2000;
    clearInterval(pres.ping);
    pres.ping = setInterval(() => {
      if (ws.readyState === 1) { try { ws.send('ping'); } catch (e) { } }
    }, 45000);
  };
  ws.onmessage = e => {
    const n = presenceParseCount(e && e.data);
    if (n !== null) { pres.count = n; presenceRender(); }
  };
  ws.onerror = () => {
    try { ws.close(); } catch (e) { }
  };
  ws.onclose = () => {
    if (pres.ws !== ws) return;
    pres.ws = null;
    clearInterval(pres.ping); pres.ping = null;
    pres.count = null; presenceRender();
    if (!pres.closed) presenceSchedule(url);
  };
}
function presenceBoot() {
  const url = presenceEndpoint();
  if (!url || typeof WebSocket !== 'function') { presenceRender(); return; }
  window.addEventListener('online', () => {
    if (!pres.closed && !pres.ws) { pres.delay = 2000; presenceConnect(url); }
  });
  window.addEventListener('offline', () => presenceDrop(false));
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden && !pres.closed && !pres.ws && (typeof navigator === 'undefined' || navigator.onLine !== false)) {
      pres.delay = 2000;
      presenceConnect(url);
    }
  });
  window.addEventListener('pagehide', () => {
    pres.closed = true;
    presenceDrop(true);
  });
  presenceConnect(url);
}

/* ---------- Canlı birlikte düzenleme (Cloudflare Durable Object) ---------- */
const COLLAB_MAX_ASSET = 400 * 1024;
const collab = {
  ws: null, url: '', room: '', viewToken: '', role: 'editor', persist: false, peerId: '', color: '#2563eb',
  name: (() => { try { return localStorage.getItem('fp_collab_name') || ''; } catch (e) { return ''; } })(),
  rev: 0, peers: new Map(), undoStack: [], redoStack: [], lastSnap: null,
  applying: false, ping: null, retry: null, delay: 1500, closed: false, reconnecting: false,
  presLast: 0, presTimer: null, dragLast: 0, dragTimer: null, cseq: 0, status: '',
  remoteQueue: [], pendingPatches: [], lastBgKey: '', sentTexIds: new Set(), lastWarnAt: 0,
  followId: '', followApplying: false, lastRoToastAt: 0,
};

function collabReadOnly() {
  return !!(collab.room && collab.role === 'viewer');
}

function collabViewerToast() {
  const now = Date.now();
  if (now - collab.lastRoToastAt < 1800) return;
  collab.lastRoToastAt = now;
  toast(L('👁 Salt okunur mod — değişiklik yapılamaz', '👁 View-only mode — editing is disabled'));
}

function collabStopFollow(notify = true) {
  if (!collab.followId || collab.followApplying) return;
  collab.followId = '';
  if (ui.modal === 'collab') collabRefreshPeersDom();
  if (notify) toast(L('Takip bırakıldı', 'Stopped following'));
}

function collabComputeFollow(peer, floors, curFi, minZoom, maxZoom) {
  if (!peer || typeof peer !== 'object') return null;
  if (peer.v3d && typeof peer.v3d.px === 'number') {
    return { mode: '3d', v3d: peer.v3d };
  }
  if (peer.view && typeof peer.view.x === 'number' && typeof peer.view.y === 'number' && typeof peer.view.z === 'number') {
    const idx = peer.view.floorId && Array.isArray(floors) ? floors.findIndex(f => f.id === peer.view.floorId) : -1;
    const z = Math.min(maxZoom || 8, Math.max(minZoom || 0.002, peer.view.z));
    return { mode: '2d', floorIdx: idx >= 0 && idx !== curFi ? idx : curFi, view: { x: peer.view.x, y: peer.view.y, z } };
  }
  return null;
}

function collabApplyFollow(peer) {
  if (!collab.followId || !peer || peer.id !== collab.followId || !P) return;
  const plan = collabComputeFollow(peer, P.floors, fi, MIN_ZOOM, MAX_ZOOM);
  if (!plan) return;
  collab.followApplying = true;
  try {
    if (plan.mode === '3d' && ui.view3d && T3) {
      T3.cam.position.set(plan.v3d.px, plan.v3d.py, plan.v3d.pz);
      T3.ctl.target.set(plan.v3d.tx, plan.v3d.ty, plan.v3d.tz);
      T3.ctl.update();
      req3D();
    } else if (plan.mode === '2d' && !ui.view3d) {
      if (plan.floorIdx !== fi) {
        fi = plan.floorIdx;
        sel = [];
        render();
        renderFloors();
        renderProps();
      }
      view.x = plan.view.x;
      view.y = plan.view.y;
      view.z = plan.view.z;
      scheduleRender();
    }
  } finally {
    collab.followApplying = false;
  }
}

function collabNewRoomId() {
  const abc = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let out = '';
  if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
    const buf = new Uint8Array(16);
    crypto.getRandomValues(buf);
    for (let i = 0; i < buf.length; i++) out += abc[buf[i] % abc.length];
    return out;
  }
  while (out.length < 16) out += abc[Math.floor(Math.random() * abc.length)];
  return out;
}

function collabEndpoint(roomId, base = PRESENCE_URL, loc = location, viewToken = '') {
  if (!roomId || !/^[A-Za-z0-9_-]{6,64}$/.test(roomId)) return '';
  let q = '';
  try { q = new URLSearchParams(loc.search || '').get('collab') || ''; } catch (e) { }
  q = q.trim();
  if (/^(off|0|false)$/i.test(q)) return '';
  const ql = q.toLowerCase();
  let raw = '';
  if (ql.startsWith('ws://') || ql.startsWith('wss://') || ql.startsWith('http://') || ql.startsWith('https://')) {
    raw = q;
  } else {
    const proto = String(loc.protocol || '').toLowerCase();
    const host = String(loc.hostname || '').toLowerCase();
    if ((proto !== 'http:' && proto !== 'https:') || !host || host === 'localhost' || host === '127.0.0.1' || host === '::1' || host === '[::1]') return '';
    raw = String(base || '').trim();
  }
  if (!raw) return '';
  const rl = raw.toLowerCase();
  if (rl.startsWith('https://')) raw = 'wss://' + raw.slice(8);
  else if (rl.startsWith('http://')) raw = 'ws://' + raw.slice(7);
  try {
    const u = new URL(raw);
    if (u.protocol !== 'ws:' && u.protocol !== 'wss:') return '';
    u.pathname = u.pathname.replace(/\/ws\/?$/, '') .replace(/\/+$/, '') + '/collab/' + roomId;
    if (viewToken) u.searchParams.set('v', viewToken);
    return u.toString();
  } catch (e) { return ''; }
}

function collabRoomUrl(roomId = collab.room, viewToken = '') {
  if (!roomId) return '';
  const base = location.protocol === 'file:' ? APP_URL : (location.origin + location.pathname + (location.search || ''));
  return base + '#room=' + encodeURIComponent(roomId) + (viewToken ? '&v=' + encodeURIComponent(viewToken) : '');
}

function collabExportState(proj = P) {
  const copy = JSON.parse(JSON.stringify(proj));
  if (copy.bg && copy.bg.src && copy.bg.src.length > 100000) copy.bg = null;
  return copy;
}

function collabRenderUI() {
  const b = $('#bCollab');
  if (!b) return;
  const n = collab.peers.size + (collab.room ? 1 : 0);
  if (!collab.room) {
    b.dataset.st = '';
    b.textContent = L('👥 Canlı', '👥 Live');
    b.title = L('Canlı birlikte düzenleme başlat veya katıl', 'Start or join live collaboration');
    return;
  }
  if (collab.role === 'viewer') {
    b.dataset.st = collab.status === 'warn' ? 'warn' : 'view';
    b.textContent = L(`👁 Salt okunur (${n})`, `👁 View-only (${n})`);
    b.title = L(`Salt okunur oturum — ${n} kişi bağlı`, `View-only session — ${n} people connected`);
    return;
  }
  b.dataset.st = collab.status === 'warn' ? 'warn' : collab.status === 'busy' ? 'busy' : 'ok';
  b.textContent = L(`👥 Canlı (${n})`, `👥 Live (${n})`);
  b.title = L(`Canlı oturumda ${n} kişi bağlı`, `${n} people in live session`);
}

function collabSend(obj) {
  if (!collab.ws || collab.ws.readyState !== 1) return false;
  try { collab.ws.send(JSON.stringify(obj)); return true; } catch (e) { return false; }
}

function collabSendPatch(patch) {
  if (!patch) return false;
  if (collabSend({ type: 'patch', patch, clientSeq: ++collab.cseq })) return true;
  if (collab.room && collab.role === 'editor' && !collab.closed) {
    collab.pendingPatches.push(patch);
    if (collab.pendingPatches.length > 200) collab.pendingPatches.shift();
  }
  return false;
}

function collabBgKey(bg) {
  return bg ? JSON.stringify(bg) : '';
}

function collabSendBgAsset(bg) {
  if (!collab.room || collab.role !== 'editor' || !collab.ws || collab.ws.readyState !== 1) return;
  if (!bg) { collabSend({ type: 'asset', kind: 'bg', data: null }); return; }
  const raw = JSON.stringify(bg);
  if (raw.length > COLLAB_MAX_ASSET) {
    toast(L('Arka plan görseli canlı aktarım için çok büyük (> 400 KB)', 'Background image is too large to sync live (> 400 KB)'));
    return;
  }
  collabSend({ type: 'asset', kind: 'bg', data: bg });
}

function collabSendTexAsset(id, data) {
  if (!collab.room || collab.role !== 'editor' || !collab.ws || collab.ws.readyState !== 1) return;
  if (!data || data.length > COLLAB_MAX_ASSET) {
    toast(L('Özel doku canlı aktarım için çok büyük (> 400 KB)', 'Custom texture is too large to sync live (> 400 KB)'));
    return;
  }
  if (collabSend({ type: 'asset', kind: 'tex', id, data })) collab.sentTexIds.add(id);
}

function collabSyncAssetsAfterCommit() {
  if (!collab.room || collab.role !== 'editor') return;
  const bgk = collabBgKey(P.bg);
  if (bgk !== collab.lastBgKey) {
    collab.lastBgKey = bgk;
    collabSendBgAsset(P.bg);
  }
  for (const t of P.textures || []) {
    if (collab.sentTexIds.has(t.id)) continue;
    const e = TEX.get(t.id);
    if (e && e.data) collabSendTexAsset(t.id, e.data);
  }
}

async function collabRequestMissingAssets(hasBg = false) {
  if (!collab.room || !collab.ws || collab.ws.readyState !== 1) return;
  if (hasBg && !P.bg) collabSend({ type: 'asset_req', kind: 'bg' });
  await ensureTextures(P);
  for (const t of P.textures || []) {
    if (!TEX.has(t.id)) collabSend({ type: 'asset_req', kind: 'tex', id: t.id });
  }
}

function collabPeerEditing(ids, peersMap = collab.peers) {
  if (!ids || !peersMap || !peersMap.size) return null;
  const set = ids instanceof Set ? ids : new Set(ids);
  if (!set.size) return null;
  for (const peer of peersMap.values()) {
    if (!peer) continue;
    for (const sid of peer.sel || []) if (set.has(sid)) return { peer, id: sid };
    if (peer.drag && Array.isArray(peer.drag.ids)) {
      for (const did of peer.drag.ids) if (set.has(did)) return { peer, id: did };
    }
  }
  return null;
}

function collabSoftLockWarn(ids) {
  if (!collab.room || !collab.peers.size) return;
  const hit = collabPeerEditing(ids);
  if (!hit) return;
  const now = Date.now();
  if (now - collab.lastWarnAt < 2500) return;
  collab.lastWarnAt = now;
  const nm = hit.peer.name || L('Başka bir kullanıcı', 'Another user');
  toast(L(`⚠ ${nm} şu an bu nesneyi düzenliyor`, `⚠ ${nm} is currently editing this object`));
}

function collabSendDrag(ids, dx = 0, dy = 0, force = false) {
  if (!collab.room || collab.role !== 'editor' || !collab.ws || collab.ws.readyState !== 1) return;
  const list = Array.isArray(ids) ? ids.slice(0, 100) : [];
  if (!list.length) {
    clearTimeout(collab.dragTimer); collab.dragTimer = null;
    collab.dragLast = Date.now();
    collabSend({ type: 'drag', ids: [] });
    return;
  }
  const now = Date.now();
  if (!force && now - collab.dragLast < 65) {
    if (!collab.dragTimer) {
      collab.dragTimer = setTimeout(() => { collab.dragTimer = null; collabSendDrag(list, dx, dy, true); }, 65);
    }
    return;
  }
  clearTimeout(collab.dragTimer); collab.dragTimer = null;
  collab.dragLast = now;
  const fl = F();
  collabSend({
    type: 'drag',
    floorId: fl ? fl.id : null,
    ids: list,
    dx: Math.round((+dx || 0) * 10) / 10,
    dy: Math.round((+dy || 0) * 10) / 10,
  });
}

function collabOnCommit(serialized) {
  if (!collab.room || collab.applying || collab.role !== 'editor') return;
  if (!collab.lastSnap) { collab.lastSnap = JSON.parse(serialized); return; }
  const next = JSON.parse(serialized);
  const patch = collabDiff(collab.lastSnap, next);
  if (patch) {
    const inv = collabInvert(collab.lastSnap, patch);
    collab.undoStack.push({ patch, inv });
    if (collab.undoStack.length > 150) collab.undoStack.shift();
    collab.redoStack = [];
    collab.lastSnap = next;
    collabSendPatch(patch);
  }
  collabSyncAssetsAfterCommit();
}

function collabApplyStep(stepPatch) {
  if (!stepPatch) return;
  collab.applying = true;
  try {
    collabApply(P, stepPatch);
    normalizeProject(P);
    ensureTextures(P);
    fi = clamp(fi, 0, P.floors.length - 1);
    sel = sel.filter(id => find(id));
    $('#pname').value = P.name;
    syncGridUI();
    collab.lastSnap = JSON.parse(JSON.stringify(P));
    collabSendPatch(stepPatch);
    refresh();
    buildLib();
    autosave();
    updateUndo();
    if (ui.view3d && T3) schedBuild3D();
  } finally {
    collab.applying = false;
  }
}

function collabUndo() {
  if (!collab.room || collab.role !== 'editor' || !collab.undoStack.length) return;
  const step = collab.undoStack.pop();
  collab.redoStack.push(step);
  collabApplyStep(step.inv);
}

function collabRedo() {
  if (!collab.room || collab.role !== 'editor' || !collab.redoStack.length) return;
  const step = collab.redoStack.pop();
  collab.undoStack.push(step);
  collabApplyStep(step.patch);
}

function collabApplyRemotePatch(patch) {
  if (!patch) return;
  if (!syncIdle()) { collab.remoteQueue.push(patch); return; }
  collab.applying = true;
  try {
    collabApply(P, patch);
    normalizeProject(P);
    ensureTextures(P);
    fi = clamp(fi, 0, P.floors.length - 1);
    sel = sel.filter(id => find(id));
    $('#pname').value = P.name;
    syncGridUI();
    collab.lastSnap = JSON.parse(JSON.stringify(P));
    refresh();
    buildLib();
    autosave();
    updateUndo();
    if (ui.view3d && T3) schedBuild3D();
    collabRequestMissingAssets(false);
  } finally {
    collab.applying = false;
  }
}

function collabFlushRemote() {
  if (!collab.remoteQueue.length || !syncIdle()) return;
  const q = collab.remoteQueue.splice(0);
  for (const p of q) collabApplyRemotePatch(p);
}

function collabApplyRemoteState(state, keepBg = false) {
  if (!state || !Array.isArray(state.floors)) return;
  collab.applying = true;
  try {
    if (ui.modal === 'templates') closeModal();
    const oldBg = keepBg ? collabClone(P && P.bg) : null;
    if (!collab.lastSnap && !collab.reconnecting && !isPristine(P) && P.id !== state.id) newTabSlot();
    const copy = JSON.parse(JSON.stringify(state));
    if (keepBg && oldBg && !copy.bg) copy.bg = oldBg;
    loadProject(copy);
    collab.lastSnap = JSON.parse(JSON.stringify(P));
    collab.lastBgKey = collabBgKey(P.bg);
    collab.undoStack = [];
    collab.redoStack = [];
    updateUndo();
  } finally {
    collab.applying = false;
  }
}

function collabFlushPending() {
  if (!collab.pendingPatches.length || collab.role !== 'editor') return;
  const pending = collab.pendingPatches.splice(0);
  collab.applying = true;
  try {
    for (const p of pending) {
      collabApply(P, p);
      collabSendPatch(p);
    }
    normalizeProject(P);
    collab.lastSnap = JSON.parse(JSON.stringify(P));
    refresh();
    autosave();
    if (ui.view3d && T3) schedBuild3D();
  } finally {
    collab.applying = false;
  }
}

function collabSendPresence(force = false) {
  if (!collab.room || !collab.ws || collab.ws.readyState !== 1 || !P) return;
  const now = Date.now();
  if (!force && now - collab.presLast < 65) {
    if (!collab.presTimer) {
      collab.presTimer = setTimeout(() => { collab.presTimer = null; collabSendPresence(true); }, 65);
    }
    return;
  }
  clearTimeout(collab.presTimer); collab.presTimer = null;
  collab.presLast = now;
  const fl = F(), fid = fl ? fl.id : null;
  const payload = {
    type: 'presence',
    name: collab.name || '',
    floorId: fid,
    x: ui.raw ? Math.round(ui.raw.x * 10) / 10 : null,
    y: ui.raw ? Math.round(ui.raw.y * 10) / 10 : null,
    sel: sel.slice(0, 100),
    view: { x: Math.round(view.x * 100) / 100, y: Math.round(view.y * 100) / 100, z: +view.z.toFixed(4), floorId: fid },
    v3d: ui.view3d && T3 ? {
      px: Math.round(T3.cam.position.x * 10) / 10, py: Math.round(T3.cam.position.y * 10) / 10, pz: Math.round(T3.cam.position.z * 10) / 10,
      tx: Math.round(T3.ctl.target.x * 10) / 10, ty: Math.round(T3.ctl.target.y * 10) / 10, tz: Math.round(T3.ctl.target.z * 10) / 10,
    } : null,
  };
  collabSend(payload);
}

function collabOverlaySvg(C, z) {
  if (!collab.room || !collab.peers.size || !P) return '';
  const fl = F(), fid = fl ? fl.id : null;
  let out = '';
  for (const peer of collab.peers.values()) {
    const col = esc(peer.color || '#2563eb');
    const sameFloor = !peer.floorId || !fid || peer.floorId === fid;
    if (sameFloor) {
      let lockedLabelAt = null;
      for (const sid of peer.sel || []) {
        const fd = find(sid);
        if (!fd) continue;
        const bb = bboxOf(fd.kind, fd.o);
        if (!bb) continue;
        const pad = 4 / z;
        out += `<rect x="${bb.x0 - pad}" y="${bb.y0 - pad}" width="${Math.max(pad, bb.x1 - bb.x0 + 2 * pad)}" height="${Math.max(pad, bb.y1 - bb.y0 + 2 * pad)}" fill="none" stroke="${col}" stroke-width="${1.8 / z}" stroke-dasharray="${5 / z} ${3 / z}" rx="${3 / z}" pointer-events="none"/>`;
        if (!lockedLabelAt) lockedLabelAt = { x: bb.x0 - pad, y: bb.y0 - pad - 4 / z };
      }
      if (peer.drag && Array.isArray(peer.drag.ids) && peer.drag.ids.length && (!peer.drag.floorId || peer.drag.floorId === fid)) {
        const dx = +peer.drag.dx || 0, dy = +peer.drag.dy || 0;
        for (const did of peer.drag.ids) {
          const fd = find(did);
          if (!fd) continue;
          const bb = bboxOf(fd.kind, fd.o);
          if (!bb) continue;
          out += `<rect x="${bb.x0 + dx}" y="${bb.y0 + dy}" width="${Math.max(4 / z, bb.x1 - bb.x0)}" height="${Math.max(4 / z, bb.y1 - bb.y0)}" fill="${col}" fill-opacity=".14" stroke="${col}" stroke-width="${2 / z}" stroke-dasharray="${6 / z} ${3 / z}" rx="${3 / z}" pointer-events="none"/>`;
          if (!lockedLabelAt) lockedLabelAt = { x: bb.x0 + dx, y: bb.y0 + dy - 4 / z };
        }
      }
      if (lockedLabelAt) {
        const nm = esc(peer.name || L('Misafir', 'Guest'));
        out += `<text x="${lockedLabelAt.x}" y="${lockedLabelAt.y}" font-size="${10 / z}" font-weight="600" fill="${col}" stroke="${C.halo}" stroke-width="${2.5 / z}" paint-order="stroke" pointer-events="none">🔒 ${nm}</text>`;
      }
      if (typeof peer.x === 'number' && typeof peer.y === 'number') {
        const x = peer.x, y = peer.y, s = 1 / z;
        const label = esc(peer.name || L('Misafir', 'Guest'));
        out += `<path d="M${x} ${y} l${12 * s} ${5 * s} l${-5 * s} ${2 * s} l${-2 * s} ${5 * s} Z" fill="${col}" stroke="${C.halo}" stroke-width="${1.5 * s}" stroke-linejoin="round" pointer-events="none"/>`;
        out += `<text x="${x + 13 * s}" y="${y + 15 * s}" font-size="${11 * s}" font-weight="600" fill="${col}" stroke="${C.halo}" stroke-width="${3 * s}" paint-order="stroke" pointer-events="none">${label}</text>`;
      }
    }
  }
  return out;
}

function collabStart() {
  const id = collabNewRoomId();
  collabJoin(id, { host: true });
}

function collabJoin(roomId, opts = {}) {
  const id = String(roomId || '').trim();
  if (!/^[A-Za-z0-9_-]{6,64}$/.test(id)) { toast(L('Geçersiz oda kodu', 'Invalid room ID')); return; }
  const vt = opts.viewToken || '';
  const url = collabEndpoint(id, PRESENCE_URL, location, vt);
  if (!url || typeof WebSocket !== 'function') {
    toast(L('Canlı düzenleme sunucusu bu adreste etkin değil', 'Live collaboration server is not configured for this address'));
    return;
  }
  if (collab.room && collab.room !== id) collabLeave(true);
  collab.closed = false;
  collab.reconnecting = false;
  collab.url = url;
  collab.room = id;
  collab.viewToken = vt;
  collab.role = vt ? 'viewer' : 'editor';
  collab.status = 'busy';
  collab.peers.clear();
  collab.remoteQueue = [];
  collab.pendingPatches = [];
  collab.sentTexIds = new Set();
  collab.lastBgKey = opts.host ? collabBgKey(P.bg) : '';
  collab.lastSnap = opts.host ? JSON.parse(JSON.stringify(P)) : null;
  collabRenderUI();
  collabConnect(url, opts);
}

function collabScheduleReconnect(url) {
  if (collab.closed || !collab.room || !url) return;
  clearTimeout(collab.retry);
  const wait = Math.round(collab.delay * (1 + Math.random() * 0.25));
  collab.delay = Math.min(15000, collab.delay * 2);
  collab.retry = setTimeout(() => collabConnect(url), wait);
}

function collabConnect(url, opts = {}) {
  if (collab.closed || !collab.room || typeof WebSocket !== 'function') return;
  if (typeof navigator !== 'undefined' && navigator.onLine === false) { collabScheduleReconnect(url); return; }
  clearTimeout(collab.retry); collab.retry = null;
  if (collab.ws) { try { collab.ws.close(1000); } catch (e) { } collab.ws = null; }
  let ws;
  try { ws = new WebSocket(url); } catch (e) { collab.status = 'warn'; collabRenderUI(); collabScheduleReconnect(url); return; }
  collab.ws = ws;
  ws.onopen = () => {
    if (collab.ws !== ws) return;
    collab.delay = 1500;
    collab.status = 'ok';
    clearInterval(collab.ping);
    collab.ping = setInterval(() => {
      if (ws.readyState === 1) { try { ws.send('ping'); } catch (e) { } }
    }, 45000);
    if (collab.reconnecting) collabSend({ type: 'resync', sinceRev: collab.rev });
    collabRenderUI();
  };
  ws.onmessage = e => {
    if (collab.ws !== ws || typeof e.data !== 'string' || e.data === 'pong') return;
    let msg;
    try { msg = JSON.parse(e.data); } catch (er) { return; }
    if (!msg || typeof msg !== 'object') return;
    if (msg.type === 'welcome') {
      collab.peerId = msg.peerId || '';
      collab.color = msg.color || '#2563eb';
      collab.role = msg.role || 'editor';
      collab.persist = !!msg.persist;
      if (msg.viewToken) collab.viewToken = msg.viewToken;
      const wasReconnecting = collab.reconnecting;
      collab.reconnecting = false;
      collab.rev = msg.rev || 0;
      collab.peers.clear();
      for (const p of msg.peers || []) if (p && p.id && p.id !== collab.peerId) collab.peers.set(p.id, p);
      if (msg.state) {
        collabApplyRemoteState(msg.state, wasReconnecting);
        if (wasReconnecting) collabFlushPending();
        collabRequestMissingAssets(!!msg.hasBg);
      } else if (collab.role === 'editor') {
        collab.lastSnap = JSON.parse(JSON.stringify(P));
        collab.lastBgKey = collabBgKey(P.bg);
        collabSend({ type: 'seed', state: collabExportState(P), clientSeq: ++collab.cseq });
        if (P.bg) collabSendBgAsset(P.bg);
        for (const t of P.textures || []) { const tx = TEX.get(t.id); if (tx && tx.data) collabSendTexAsset(t.id, tx.data); }
        collabFlushPending();
      }
      collabSendPresence(true);
      collabRenderUI();
      if (ui.modal === 'collab') collabModal();
      return;
    }
    if (msg.type === 'state') {
      collab.rev = msg.rev || collab.rev;
      if (msg.state) {
        collabApplyRemoteState(msg.state, true);
        collabFlushPending();
        collabRequestMissingAssets(!!msg.hasBg);
      } else if (collab.role === 'editor' && P) {
        collab.lastSnap = JSON.parse(JSON.stringify(P));
        collabSend({ type: 'seed', state: collabExportState(P), clientSeq: ++collab.cseq });
        if (P.bg) collabSendBgAsset(P.bg);
        collabFlushPending();
      }
      collabRenderUI();
      return;
    }
    if (msg.type === 'resync_needed') {
      collabSend({ type: 'resync', sinceRev: collab.rev });
      return;
    }
    if (msg.type === 'ack') {
      if (typeof msg.rev === 'number') collab.rev = Math.max(collab.rev, msg.rev);
      return;
    }
    if (msg.type === 'patch') {
      if (msg.from === collab.peerId) return;
      if (typeof msg.rev === 'number') collab.rev = Math.max(collab.rev, msg.rev);
      collabApplyRemotePatch(msg.patch);
      return;
    }
    if (msg.type === 'drag' && msg.from && msg.from !== collab.peerId) {
      const p = collab.peers.get(msg.from) || { id: msg.from, color: msg.color || '#2563eb', name: msg.name || '', sel: [] };
      p.drag = Array.isArray(msg.ids) && msg.ids.length ? { floorId: msg.floorId || null, ids: msg.ids, dx: msg.dx || 0, dy: msg.dy || 0 } : null;
      collab.peers.set(msg.from, p);
      if (!ui.view3d) drawPreview();
      return;
    }
    if (msg.type === 'asset') {
      if (msg.kind === 'bg') {
        collab.applying = true;
        try {
          P.bg = msg.data ? collabClone(msg.data) : null;
          collab.lastBgKey = collabBgKey(P.bg);
          collab.lastSnap = JSON.parse(JSON.stringify(P));
          refresh();
          autosave();
        } finally { collab.applying = false; }
      } else if (msg.kind === 'tex' && msg.id && typeof msg.data === 'string' && msg.data.startsWith('data:image/')) {
        cacheTex(msg.id, msg.data);
        dbPut('textures', { id: msg.id, data: msg.data }).catch(() => { });
        collab.sentTexIds.add(msg.id);
        render();
        if (ui.view3d && T3) schedBuild3D();
      }
      return;
    }
    if (msg.type === 'asset_rejected') {
      toast(L('Görsel canlı oda limiti (400 KB) nedeniyle gönderilemedi', 'Image exceeds the 400 KB live sync limit'));
      return;
    }
    if (msg.type === 'persist') {
      collab.persist = !!msg.persist;
      if (ui.modal === 'collab') collabModal();
      return;
    }
    if (msg.type === 'error' && msg.code === 'readonly') {
      collabViewerToast();
      return;
    }
    if (msg.type === 'peer_join' && msg.peer && msg.peer.id !== collab.peerId) {
      collab.peers.set(msg.peer.id, msg.peer);
      collabRenderUI();
      if (ui.modal === 'collab') collabModal();
      else if (!ui.view3d) drawPreview();
      return;
    }
    if (msg.type === 'presence' && msg.peer && msg.peer.id !== collab.peerId) {
      const old = collab.peers.get(msg.peer.id);
      if (old && old.drag && msg.peer.drag === undefined) msg.peer.drag = old.drag;
      collab.peers.set(msg.peer.id, msg.peer);
      if (collab.followId === msg.peer.id) collabApplyFollow(msg.peer);
      if (ui.modal === 'collab') collabRefreshPeersDom();
      if (!ui.view3d) drawPreview();
      return;
    }
    if (msg.type === 'peer_leave' && msg.peerId) {
      collab.peers.delete(msg.peerId);
      if (collab.followId === msg.peerId) collab.followId = '';
      collabRenderUI();
      if (ui.modal === 'collab') collabModal();
      else if (!ui.view3d) drawPreview();
    }
  };
  ws.onerror = () => { try { ws.close(); } catch (e) { } };
  ws.onclose = () => {
    if (collab.ws !== ws) return;
    collab.ws = null;
    clearInterval(collab.ping); collab.ping = null;
    if (collab.closed || !collab.room) return;
    collab.reconnecting = true;
    collab.status = 'warn';
    collabRenderUI();
    if (ui.modal === 'collab') collabModal();
    collabScheduleReconnect(url);
  };
}

function collabLeave(silent = false) {
  collab.closed = true;
  clearTimeout(collab.retry); collab.retry = null;
  clearInterval(collab.ping); collab.ping = null;
  clearTimeout(collab.presTimer); collab.presTimer = null;
  clearTimeout(collab.dragTimer); collab.dragTimer = null;
  const ws = collab.ws; collab.ws = null;
  if (ws) { try { ws.close(1000); } catch (e) { } }
  const was = !!collab.room;
  collab.room = ''; collab.url = ''; collab.viewToken = ''; collab.role = 'editor'; collab.persist = false; collab.peerId = '';
  collab.rev = 0; collab.status = ''; collab.reconnecting = false; collab.followId = ''; collab.followApplying = false; collab.peers.clear();
  collab.remoteQueue = []; collab.pendingPatches = []; collab.sentTexIds.clear(); collab.lastBgKey = '';
  collab.undoStack = []; collab.redoStack = []; collab.lastSnap = null;
  if (P) { hist = [JSON.stringify(P)]; hi = 0; updateUndo(); }
  collabRenderUI();
  if (!ui.view3d && P) drawPreview();
  if (ui.modal === 'collab') collabModal();
  if (was && !silent) toast(L('Canlı oturumdan ayrıldınız', 'Left live session'));
}

function collabPeersHtml() {
  if (!collab.room) return '';
  const flMap = new Map((P.floors || []).map(f => [f.id, f.name]));
  const meName = esc(collab.name || L('Sen', 'You'));
  const selfPill = `<span class="collab-peer"><i style="background:${esc(collab.color)}"></i><b>${meName}</b> (${L('Sen', 'You')})</span>`;
  const others = [...collab.peers.values()].map(p => {
    const nm = esc(p.name || L('Misafir', 'Guest'));
    const fl = p.floorId && flMap.get(p.floorId) ? ` · ${esc(flMap.get(p.floorId))}` : '';
    const roTag = p.role === 'viewer' ? ' 👁' : '';
    const flw = collab.followId === p.id;
    return `<span class="collab-peer"><i style="background:${esc(p.color || '#2563eb')}"></i><span>${nm}${roTag}${fl}</span><button type="button" data-clfollow="${esc(p.id)}">${flw ? L('✕ Bırak', '✕ Following') : L('👁 Takip et', '👁 Follow')}</button></span>`;
  }).join('');
  return `<div class="collab-peers" id="collabPeers">${selfPill}${others}</div>`;
}

function collabRefreshPeersDom() {
  const el = $('#collabPeers');
  if (el) el.outerHTML = collabPeersHtml();
}

function collabParseJoinInput(val) {
  const s = String(val || '').trim();
  if (!s) return null;
  if (/^[A-Za-z0-9_-]{6,64}$/.test(s)) return { roomId: s, viewToken: '' };
  const m = /#?room=([A-Za-z0-9_-]{6,64})(?:&v=([A-Za-z0-9_-]{4,64}))?/.exec(s);
  if (m) return { roomId: m[1], viewToken: m[2] || '' };
  try {
    const u = new URL(s);
    const qr = u.searchParams.get('room');
    if (qr && /^[A-Za-z0-9_-]{6,64}$/.test(qr)) return { roomId: qr, viewToken: u.searchParams.get('v') || '' };
  } catch (e) { }
  return null;
}

function collabModal() {
  const nameRow = `<div class="row" style="margin-bottom:10px"><label class="muted" for="collabName" style="min-width:90px">${L('Adınız', 'Your name')}</label><input id="collabName" class="collab-name" maxlength="40" placeholder="${L('İsteğe bağlı görünen ad', 'Optional display name')}" value="${esc(collab.name || '')}"></div>`;
  if (!collab.room) {
    openModal(`<h2>👥 ${L('Canlı birlikte düzenleme', 'Live collaboration')} <button class="btn sm" data-close>✕</button></h2>
      <p class="muted" style="margin-top:0">${L('Aynı planı gerçek zamanlı olarak birlikte düzenleyin. Odalar geçicidir: herkes çıktığında sunucudaki oturum verisi silinir.', 'Edit the same plan together in real time. Rooms are ephemeral: session data is cleared from memory when everyone leaves.')}</p>
      ${nameRow}
      <div class="row" style="margin-bottom:12px"><button class="btn primary" data-cl="start">🚀 ${L('Canlı oturum başlat', 'Start live session')}</button></div>
      <div class="row"><input id="collabJoinInp" class="collab-name" placeholder="${L('Oda linki veya kodu yapıştır…', 'Paste room link or ID…')}"><button class="btn" data-cl="join">${L('Katıl', 'Join')}</button></div>`, 'collab');
    return;
  }
  const url = collabRoomUrl(collab.room);
  const viewUrl = collab.role === 'editor' && collab.viewToken ? collabRoomUrl(collab.room, collab.viewToken) : '';
  const qr = url && url.length <= SHARE_QR_MAX ? qrSvg(url, 'M', 4) : '';
  const stTxt = collab.status === 'warn' ? L('⚠ Bağlantı kesildi — yeniden bağlanılıyor', '⚠ Disconnected — reconnecting')
    : collab.status === 'busy' ? L('⟳ Bağlanıyor…', '⟳ Connecting…')
    : collab.role === 'viewer' ? L('👁 Salt okunur — plan anlık güncelleniyor', '👁 View-only — live updates active')
    : L('● Bağlı — değişiklikler anlık eşitleniyor', '● Connected — edits sync live');
  const editorLinks = collab.role === 'editor' ? `
      <div class="row"><input id="clUrl" readonly value="${esc(url)}" style="flex:1;min-width:200px"><button class="btn sm primary" data-cl="copy">📋 ${L('Düzenleme linki', 'Copy edit link')}</button>${navigator.share ? `<button class="btn sm" data-cl="share">📤 ${L('Paylaş…', 'Share…')}</button>` : ''}</div>
      ${viewUrl ? `<div class="row" style="margin-top:6px"><input id="clViewUrl" readonly value="${esc(viewUrl)}" style="flex:1;min-width:200px"><button class="btn sm" data-cl="copyview">👁 ${L('Salt okunur link', 'Copy view-only link')}</button></div>` : ''}
      <label class="chk-pill" style="margin-top:8px"><input type="checkbox" id="clPersist" ${collab.persist ? 'checked' : ''}> <span>${L('Odayı kalıcı kaydet (herkes çıksa da kalsın)', 'Persist room (keep snapshot even after everyone leaves)')}</span></label>
      <p class="muted" style="font-size:12px;margin-bottom:0">${L('Düzenleme linki olanlar planı değiştirebilir; salt okunur link yalnızca izlemeye ve takip etmeye izin verir.', 'Edit links allow changes; view-only links allow inspecting and following only.')}</p>`
    : `<p class="muted" style="font-size:12px;margin:0">${L('Salt okunur moddasınız: katları değiştirebilir, 3B gezebilir ve diğer katılımcıları takip edebilirsiniz.', 'You are in view-only mode: you can switch floors, orbit in 3D, and follow other participants.')}</p>`;
  openModal(`<h2>👥 ${L('Canlı birlikte düzenleme', 'Live collaboration')} <button class="btn sm" data-close>✕</button></h2>
    <p style="margin:0 0 8px;font-size:12.5px"><b>${stTxt}</b></p>
    ${nameRow}
    ${collabPeersHtml()}
    <div class="sh-out">
      ${collab.role === 'editor' && qr ? `<div class="sh-qr">${qr}</div>` : ''}
      ${editorLinks}
    </div>
    <div class="row" style="margin-top:12px"><button class="btn" data-cl="leave">🚪 ${L('Oturumdan ayrıl', 'Leave session')}</button></div>`, 'collab');
}

$('#modal').addEventListener('input', e => {
  if (ui.modal === 'collab' && e.target && e.target.id === 'collabName') {
    collab.name = String(e.target.value || '').trim().slice(0, 40);
    try { localStorage.setItem('fp_collab_name', collab.name); } catch (er) { }
    collabSendPresence(true);
    collabRefreshPeersDom();
  }
});
$('#modal').addEventListener('change', e => {
  if (ui.modal === 'collab' && e.target && e.target.id === 'clPersist') {
    const val = !!e.target.checked;
    collab.persist = val;
    collabSend({ type: 'set_persist', persist: val });
  }
});
$('#modal').addEventListener('click', e => {
  if (ui.modal !== 'collab') return;
  const flw = e.target.closest('[data-clfollow]');
  if (flw) {
    const pid = flw.dataset.clfollow;
    collab.followId = collab.followId === pid ? '' : pid;
    if (collab.followId && collab.peers.has(collab.followId)) {
      collabApplyFollow(collab.peers.get(collab.followId));
    }
    collabRefreshPeersDom();
    return;
  }
  const b = e.target.closest('[data-cl]');
  if (!b) return;
  const a = b.dataset.cl;
  if (a === 'start') collabStart();
  else if (a === 'join') {
    const parsed = collabParseJoinInput($('#collabJoinInp')?.value);
    if (!parsed) { toast(L('Geçerli bir oda linki veya kodu girin', 'Enter a valid room link or ID')); return; }
    collabJoin(parsed.roomId, { viewToken: parsed.viewToken });
  } else if (a === 'copy') {
    copyText($('#clUrl').value).then(ok => toast(ok ? L('Oda linki kopyalandı', 'Room link copied') : L('Kopyalanamadı', 'Could not copy')));
  } else if (a === 'copyview') {
    copyText($('#clViewUrl').value).then(ok => toast(ok ? L('Salt okunur link kopyalandı', 'View-only link copied') : L('Kopyalanamadı', 'Could not copy')));
  } else if (a === 'share') {
    navigator.share({ title: P.name, url: $('#clUrl').value }).catch(() => { });
  } else if (a === 'leave') {
    collabLeave(false);
  }
});

function collabBoot() {
  collabRenderUI();
  let qr = '', qv = '';
  try {
    const sp = new URLSearchParams(location.search || '');
    qr = sp.get('room') || '';
    qv = sp.get('v') || '';
  } catch (e) { }
  if (qr && /^[A-Za-z0-9_-]{6,64}$/.test(qr)) collabJoin(qr, { viewToken: qv });
  window.addEventListener('online', () => {
    if (collab.room && !collab.closed && !collab.ws && collab.url) { collab.delay = 1500; collabConnect(collab.url); }
  });
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden && collab.room && !collab.closed && !collab.ws && collab.url && (typeof navigator === 'undefined' || navigator.onLine !== false)) {
      collab.delay = 1500; collabConnect(collab.url);
    }
  });
  window.addEventListener('pagehide', () => {
    if (collab.ws) { collab.closed = true; try { collab.ws.close(1000); } catch (e) { } }
  });
}

/* ---------- Şablonlar ---------- */
function tplCtx() {
  const f = F();
  return {
    W: (x1, y1, x2, y2) => { const w = mkWall({ x: x1, y: y1 }, { x: x2, y: y2 }); f.walls.push(w); return w; },
    rect: addRectWalls,
    op: (w, d, id, extra) => { const o = mkOp(OPDEF[id], w, d); Object.assign(o, extra || {}); f.ops.push(o); },
    fu: (id, x, y, rot = 0, label) => { const o = mkFurn(BYID[id], x, y, rot); if (label) o.label = label; f.furn.push(o); },
    room: (x, y, name, color, fl) => { const r = autoRoomAt({ x, y }, true); if (r) { r.name = name; if (color) r.color = color; r.floor = fl || 'none'; } },
  };
}
